//===- mac_sparse.cc --------------------------------------------*- C++ -*-===//
//
// ops capture kernel for sparse MAC config mode (0, 1, 5) `4x16_16x8`
// (GENERATED by tools/gen_mac_sparse.py). Per tile and signedness flavour it builds the sparse B operand with update() from a stored-data block and a mask block,
// then runs mul, mul, negmul, mac, msc, negmac, negmsc, addmac, addmsc, submac, submsc.
// Chunk layout: 9 operand blocks of T tiles (A0 D0 M0 A1 D1 M1 A2 D2 M2).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

// Peano builds see no Chess-side define; the stream/ADF half of aie_api is not needed.
#ifndef __AIE_API_AIE_ADF_HPP__
#define __AIE_API_AIE_ADF_HPP__
#endif
#include <aie_api/aie.hpp>

#define T 2
#define OUT_WORDS_PER_TILE 1408

#define STORE(r, dst) \
  do { aie::accum<acc32, 32> w(r); aie::store_v((dst), w.to_vector<int32>(0)); } while (0)

extern "C" {

void mac_sparse(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  uint8_t *in2 = in + 0 + T * 64 + T * 64;
  uint8_t *in3 = in + 0 + T * 64 + T * 64 + T * 16;
  uint8_t *in4 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64;
  uint8_t *in5 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64;
  uint8_t *in6 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16;
  uint8_t *in7 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16 + T * 64;
  uint8_t *in8 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64;
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v64int8 a0 = *(v64int8 *)(in0 + n * 64);
      v64int8 d0 = *(v64int8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128int8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v64int8 a1 = *(v64int8 *)(in3 + n * 64);
      v64int8 d1 = *(v64int8 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v128int8_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v64int8 a2 = *(v64int8 *)(in6 + n * 64);
      v64int8 d2 = *(v64int8 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v128int8_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v32acc32 r0 = mul_4x16_16x8(a0, b0);
      v32acc32 r1 = mul_4x16_16x8(a1, b1);
      v32acc32 r2 = negmul_4x16_16x8(a2, b2);
      v32acc32 r3 = mac_4x16_16x8(a2, b2, r0);
      v32acc32 r4 = msc_4x16_16x8(a2, b2, r0);
      v32acc32 r5 = negmac_4x16_16x8(a2, b2, r0);
      v32acc32 r6 = negmsc_4x16_16x8(a2, b2, r0);
      v32acc32 r7 = addmac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r8 = addmsc_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r9 = submac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r10 = submsc_4x16_16x8(a2, b2, r0, r1);
      STORE(r0, o + 0);
      STORE(r1, o + 32);
      STORE(r2, o + 64);
      STORE(r3, o + 96);
      STORE(r4, o + 128);
      STORE(r5, o + 160);
      STORE(r6, o + 192);
      STORE(r7, o + 224);
      STORE(r8, o + 256);
      STORE(r9, o + 288);
      STORE(r10, o + 320);
    }
    { // su
      v64int8 a0 = *(v64int8 *)(in0 + n * 64);
      v64uint8 d0 = *(v64uint8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128uint8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v64int8 a1 = *(v64int8 *)(in3 + n * 64);
      v64uint8 d1 = *(v64uint8 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v128uint8_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v64int8 a2 = *(v64int8 *)(in6 + n * 64);
      v64uint8 d2 = *(v64uint8 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v128uint8_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v32acc32 r0 = mul_4x16_16x8(a0, b0);
      v32acc32 r1 = mul_4x16_16x8(a1, b1);
      v32acc32 r2 = negmul_4x16_16x8(a2, b2);
      v32acc32 r3 = mac_4x16_16x8(a2, b2, r0);
      v32acc32 r4 = msc_4x16_16x8(a2, b2, r0);
      v32acc32 r5 = negmac_4x16_16x8(a2, b2, r0);
      v32acc32 r6 = negmsc_4x16_16x8(a2, b2, r0);
      v32acc32 r7 = addmac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r8 = addmsc_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r9 = submac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r10 = submsc_4x16_16x8(a2, b2, r0, r1);
      STORE(r0, o + 352);
      STORE(r1, o + 384);
      STORE(r2, o + 416);
      STORE(r3, o + 448);
      STORE(r4, o + 480);
      STORE(r5, o + 512);
      STORE(r6, o + 544);
      STORE(r7, o + 576);
      STORE(r8, o + 608);
      STORE(r9, o + 640);
      STORE(r10, o + 672);
    }
    { // us
      v64uint8 a0 = *(v64uint8 *)(in0 + n * 64);
      v64int8 d0 = *(v64int8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128int8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v64uint8 a1 = *(v64uint8 *)(in3 + n * 64);
      v64int8 d1 = *(v64int8 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v128int8_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v64uint8 a2 = *(v64uint8 *)(in6 + n * 64);
      v64int8 d2 = *(v64int8 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v128int8_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v32acc32 r0 = mul_4x16_16x8(a0, b0);
      v32acc32 r1 = mul_4x16_16x8(a1, b1);
      v32acc32 r2 = negmul_4x16_16x8(a2, b2);
      v32acc32 r3 = mac_4x16_16x8(a2, b2, r0);
      v32acc32 r4 = msc_4x16_16x8(a2, b2, r0);
      v32acc32 r5 = negmac_4x16_16x8(a2, b2, r0);
      v32acc32 r6 = negmsc_4x16_16x8(a2, b2, r0);
      v32acc32 r7 = addmac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r8 = addmsc_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r9 = submac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r10 = submsc_4x16_16x8(a2, b2, r0, r1);
      STORE(r0, o + 704);
      STORE(r1, o + 736);
      STORE(r2, o + 768);
      STORE(r3, o + 800);
      STORE(r4, o + 832);
      STORE(r5, o + 864);
      STORE(r6, o + 896);
      STORE(r7, o + 928);
      STORE(r8, o + 960);
      STORE(r9, o + 992);
      STORE(r10, o + 1024);
    }
    { // uu
      v64uint8 a0 = *(v64uint8 *)(in0 + n * 64);
      v64uint8 d0 = *(v64uint8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128uint8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v64uint8 a1 = *(v64uint8 *)(in3 + n * 64);
      v64uint8 d1 = *(v64uint8 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v128uint8_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v64uint8 a2 = *(v64uint8 *)(in6 + n * 64);
      v64uint8 d2 = *(v64uint8 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v128uint8_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v32acc32 r0 = mul_4x16_16x8(a0, b0);
      v32acc32 r1 = mul_4x16_16x8(a1, b1);
      v32acc32 r2 = negmul_4x16_16x8(a2, b2);
      v32acc32 r3 = mac_4x16_16x8(a2, b2, r0);
      v32acc32 r4 = msc_4x16_16x8(a2, b2, r0);
      v32acc32 r5 = negmac_4x16_16x8(a2, b2, r0);
      v32acc32 r6 = negmsc_4x16_16x8(a2, b2, r0);
      v32acc32 r7 = addmac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r8 = addmsc_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r9 = submac_4x16_16x8(a2, b2, r0, r1);
      v32acc32 r10 = submsc_4x16_16x8(a2, b2, r0, r1);
      STORE(r0, o + 1056);
      STORE(r1, o + 1088);
      STORE(r2, o + 1120);
      STORE(r3, o + 1152);
      STORE(r4, o + 1184);
      STORE(r5, o + 1216);
      STORE(r6, o + 1248);
      STORE(r7, o + 1280);
      STORE(r8, o + 1312);
      STORE(r9, o + 1344);
      STORE(r10, o + 1376);
    }
  }
  event1();
}

} // extern "C"
